630	import org.springframework.stereotype.Service;
631	
632	/**
633	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
634	 * so tests can assert side-effects by reading that file — the second test-assertion channel
635	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
636	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
637	 *
638	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
639	 * SYNC) so a test reads the record immediately.
640	 */
641	@Service
642	public class Audit {
643	
644	    private final Path file;
645	
646	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
647	        this.file = Path.of(path);
648	    }
649	
650	    /** Append one audit record. Tests assert the exact line(s) in the file. */
651	    public synchronized void record(String entry) {
652	        try {
653	            Path parent = file.toAbsolutePath().getParent();
654	            if (parent != null) {
655	                Files.createDirectories(parent);
656	            }
657	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
658	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
659	        } catch (IOException e) {
660	            throw new UncheckedIOException(e);
661	        }
662	    }
663	
664	    /** The signed-in user a write names in its X-User header ("" when it names none). */
665	    public static String user(ServerHttpConnection connection) {
666	        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
667	        return header == null ? "" : header.getValue();
668	    }
669	
670	    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
671	    public static String line(String event, String sheetId, String user, String... fields) {
672	        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
673	                .append(" by=").append(user == null ? "" : user.trim());
674	        for (String field : fields) {
675	            line.append(' ').append(field);
676	        }
677	        return line.toString();
678	    }
679	
680	    /** Remove the audit file. */
681	    public synchronized void clear() {
682	        try {
683	            Files.deleteIfExists(file);
684	        } catch (IOException e) {
685	            throw new UncheckedIOException(e);
686	        }
687	    }
