# POST /api/sheets/{sheetId}/people/{personId}/claims — add a claim to a person. Body
# {"amount":"12.50","date":"yyyy-mm-dd","note":"..."}; a blank date is the sheet's today. An amount
# that is not a number of 0.00 or more with up to two decimals, or a date that is not real, is
# refused with 400 and nothing is stored; 404 for a person not on the sheet.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: add
  govern: [ transaction ]
add:
  class: net.officefloor.hq.app.claim.AddClaim
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAdded
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class AddClaim {
    public void add(@Val ClaimInput input, @Val Person person, Claims claims, Sheets sheets, Out<Claim> claimOut) {
        claimOut.set(claims.add(person.sheetId(), person.id(), input.amount(),
                input.date() != null ? input.date() : sheets.today(person.sheetId()), input.note()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    // Claim is a record, so the edited claim is published in place of the loaded one.
    public void apply(@Val ClaimInput input, @Val Claim claim, Claims claims, Sheets sheets,
            Out<ClaimResponse> responseOut) {
        Claim edited = claim.with(input, input.date() != null ? input.date() : sheets.today(claim.sheetId()));
        claims.save(edited);
        responseOut.set(ClaimResponse.from(edited));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithEditedClaim {
    public void respond(@Val ClaimResponse claim, ObjectResponse<ClaimResponse> response) {
        response.send(claim);
    }
}
# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)
